import{_ as i,o as a,c as p,am as s}from"./chunks/framework._FJXuPhs.js";const d=JSON.parse('{"title":"客诉项目20240416","description":"","frontmatter":{"title":"客诉项目20240416","excerpt":"准备还是简历优化包装下，然后找一个自研，好好加油。","date":"2024-04-16 19:24:08","updated":"2024-04-16 19:24:08"},"headers":[],"relativePath":"面试准备/Java面试准备 2024版本/客诉项目速通/客诉项目20240416.md","filePath":"面试准备/Java面试准备 2024版本/客诉项目速通/客诉项目20240416.md","lastUpdated":null}'),e={name:"面试准备/Java面试准备 2024版本/客诉项目速通/客诉项目20240416.md"};function n(t,l,o,r,c,u){return a(),p("div",null,[...l[0]||(l[0]=[s(`<p><a href="/java-site/面试准备/Java面试准备 2024版本/客诉项目速通/">客诉项目速通</a></p><p>项目文档地址：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>链接：https://pan.baidu.com/s/1oalDtlQR_vMYqE6_ArPJfA </span></span>
<span class="line"><span>提取码：b7JB </span></span>
<span class="line"><span></span></span>
<span class="line"><span>面试高频题（仅仅作为参考）</span></span>
<span class="line"><span>链接：https://pan.baidu.com/s/1JOQ19VXqaXA68n4KMXe-Ig </span></span>
<span class="line"><span>提取码：z5cW</span></span></code></pre></div><h3 id="问题收集" tabindex="-1">问题收集 <a class="header-anchor" href="#问题收集" aria-label="Permalink to &quot;问题收集&quot;">​</a></h3><ul><li>1、是否需要包装公司？（个人目前的需求是：打算去自研公司，然后外包不想去，简历需要改善一下）</li></ul><h3 id="客诉项目" tabindex="-1">客诉项目 <a class="header-anchor" href="#客诉项目" aria-label="Permalink to &quot;客诉项目&quot;">​</a></h3><p>客诉是该中台下的一个服务</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240417191845.png" alt="image.png"></p><p>相关业务</p><ul><li>1、货主通过物流平台进行创建发货订单操作，司机通过物流平台进行接货，中途如果产生纠纷会创建客诉单</li><li>2、客户对客诉单进行审核操作，如果涉及到钱相关的客诉类型需要客服领导进行审核操作</li><li>3、</li></ul><p>服务调用</p><ul><li>模块业务和其他部门交互采用 mq 消息形式</li><li>部分接口使用 rpc同步远程调用</li></ul><p>单据类型</p><ul><li>1、申诉单：中途如果产生纠纷会创建客诉单 <ul><li>例如：货主没有把货物放到指定地方、货主辱骂司机、货主没有提前告诉司机需要跟车等原因，正常交易货主不退定金等</li></ul></li><li>2、催收单：如果有公司垫付费用的情况还会涉及催收单和申诉单的业务产生</li><li>3、申请单</li><li>4、客诉单：货主投诉司机的情况，例如(司机迟到，司机车型不符，司机辱骂货主，冷运货物司机未带保温毯等)。</li></ul><p>系统业务背景：部门主要负责整个客诉系统的送代和优化，提升客服的办事效率。</p><p>个人职责</p><ul><li>1、负责日常需求开发和技术文档编写，如：退佣、退定金、重开等逻辑开发</li><li>2、优化客诉后台客诉单详情页展示接口。从5 秒多优化到 1秒多展示</li><li>3、对整个客诉平台进行拆分，拆分成催收、客诉、申请单三个独立微服务方便维护和职责划分。</li><li>4、组织其他部门讨论客诉单创建过程中分布式事务解决方案，并编写处理逻辑</li><li>5、设计分布式锁防止客诉单创建页面重复提交以及定时分单任务重复扫描</li><li>6、对日常监控平台检测的慢 sql 进行调优，以及优化大表的查询速度</li><li>7、独立定位线上 redis 内存溢出问题以及因 flume 异常导致磁盘占用达到阈值告警问题。</li></ul><p>简历项目内容：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240416225813.png" alt="image.png"></p><hr><h3 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h3><p>项目架构</p><ul><li>Springboot + cloud + es + rocketMQ + redis + mysql</li></ul><p>项目介绍：略 自我发挥</p><ul><li>客诉单 <ul><li>数据来源 <ul><li>1、司机或者货主自己在平台进行申诉（下拉框选择 + 截图 + 文字说明 → 进行提交）</li><li>2、联系客服，客服创建</li></ul></li><li>表单信息 <ul><li>脱俗类型、具体投诉内容、图片说明、投诉方向</li><li>重复校验（如果该运单有未办结的客诉单存在就不允许创建）</li></ul></li><li>创建后的操作 <ul><li>1、进行冻结订单</li><li>2、客诉单入库（数据库主从结构，返回ID）</li><li>3、图片上传，oss 上传，然后关联客诉单 ID</li><li>4、发送 mq 消息，（将客诉单的ID进行发送解耦），客诉服务进行消费 <ul><li>消费操作 <ul><li>根据客诉单 ID 获取到数据库客诉单的详细信息，然后数据库信息 + 图片信息</li><li>组装成 es 需要的数据类型（为了减少 es 占用存储空间，所以只存一些状态，比如有无举证这些状态，而并不是存真正的举证图片地址进 es） <ul><li>客诉单ID</li><li>投诉类型</li><li>客诉单工单 ID</li><li>是否有举证图片</li><li>是否重开过</li><li>投诉单状态（待领取、已领取、审核中、审核完成、已办结）</li><li>时间等</li></ul></li></ul></li></ul></li><li>5、接口发送（投诉单类型 ID 和 客诉单 ID 传给工单服务（其他的部门））</li></ul></li></ul></li></ul><h4 id="客诉单" tabindex="-1">客诉单 <a class="header-anchor" href="#客诉单" aria-label="Permalink to &quot;客诉单&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240417193011.png" alt="image.png"></p><p>1、客诉单表单提交 2、后续任务</p><p>2.1 远程调用运单服务进行冻结订单 2.2 客诉单进行入库操作 2.3 举证图片入库操作 2.4 入库后发送MQ 消息到客诉服务（载体是 客诉单 ID）</p><p>客诉服务操作</p><p>拿到这个ID后，进行查询详细信息 + 图片信息，进行组装，然后放入到 ES 中</p><p>2.5 将客诉单ID + 投诉类型ID 传给工单服务</p><p>工单服务操作（其他部门）</p><p>对方服务会根据规则引擎生成客诉单不同投诉类型的一个模板，返回 true 或者 false 给这边（如果返回 true，则创建成功，当用户后续打开客诉单详情会再根据客诉单 ID 去进行拉取操作）</p><p>2.6 记录相关操作（事件记录）</p><p>2.7 外呼表差人一条记录，存放司机和货主的身份信息，名称手机号之类的。（类似企微提醒之类的）【这里数据库使用到了分表操作，动态表名】</p><p>2.8 异常流程回顾（使用 rocketmq 进行分布式事务回滚操作）</p><p>客诉单分配到客服操作（定时任务操作）→ 算法分配</p><hr><h4 id="催收单" tabindex="-1">催收单 <a class="header-anchor" href="#催收单" aria-label="Permalink to &quot;催收单&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240417193759.png" alt="image.png"></p><p>押金（司机给货主的，当货物送达后，货主退回押金给司机）</p><p>数据产生背景：</p><p>当司机提起客诉（比如货主不退钱），客服那边可以在客诉单详情</p><p>进行垫付操作（按钮操作），客服输入金额后，进行提交</p><p>【生成一个垫付事件】</p><p>退钱到司机后，这边会创建一个催收单接口，会把客诉单 id 和退钱状态传到这个接口，这个接口会进行生成催收记录</p><p>并保存到ES中，记录表添加一条记录</p><p>催收表记录，会有专门的客服人员进行审核操作</p><p>催收操作</p><p>客服打电话催货主进行还款操作</p><p>1.1 如果货主坚持不还款，催收单页面会有一个用户打标操作</p><p>当打标操作后，货主会在再次发货后，第一天会进行一下提示；三天后还没有还款，会进行限制发货操作，并且弹窗一直存在</p><p>1.2 修改催收单金额操作</p><p>1.3 拉黑用户操作</p><hr><h4 id="申诉单" tabindex="-1">申诉单 <a class="header-anchor" href="#申诉单" aria-label="Permalink to &quot;申诉单&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240417194111.png" alt="image.png"></p><p>申诉单</p><p>例如押金问题审判完后，货主不满，继续提起申诉操作（收集足够证据后进行申诉操作）【只允许一次申诉机会】</p><p>如果申诉的确合理，会反向向司机生成一个催收单</p><hr><h4 id="申请单" tabindex="-1">申请单 <a class="header-anchor" href="#申请单" aria-label="Permalink to &quot;申请单&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240417194812.png" alt="image.png"></p><p>客诉详情页 → 申请安全（客服服务操作）</p><p>点击申请按钮</p><p>1、<strong>调用工单服务接口，创建一个审核单</strong> 2、审核结果会调用客诉服务提供的远程接口，该接口的作用： 根据审核结果， 拒绝：将申请单中状态更新为拒绝状态，es 中同步更改，记录表会插入一条记录 成功，客诉平台调用其他部门去处理这个申请单具体的业务，其他部门操作完具体的业务后，会调用客诉服务的接口做一些状态的修改和记录</p><hr><p>1、RocketMQ（项目发布流程，半小时，事务回顾） 2、Sentinel(限流算法） 3、Gateway（断言，配置方式） 4、OpenFegin（远程调用原理，Ribbon） 5、</p><p>中台：将一些业务集中到一个地方 客诉中台</p><p>客单 → 运单（司机接单） →</p><p>查询：放入到 ES 中（关键信息）</p><p>详情 → 再通过数据库进行查询</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240417133059.png" alt="image.png"></p><h3 id="个人职责" tabindex="-1">个人职责 <a class="header-anchor" href="#个人职责" aria-label="Permalink to &quot;个人职责&quot;">​</a></h3><ul><li>负责客诉单重开逻辑的编写</li><li>负责退佣金逻辑的编写</li><li>优化客诉单详情接口</li><li>分布式事务异常回滚</li><li>负责接入 sentinel</li><li>基于 ddd 分层架构拆分客诉单，将客诉单平台一个单独的服务拆分</li></ul><h3 id="客诉问点答疑" tabindex="-1">客诉问点答疑 <a class="header-anchor" href="#客诉问点答疑" aria-label="Permalink to &quot;客诉问点答疑&quot;">​</a></h3><p>客诉单，进行提交操作</p><ul><li>1、投诉单创建：中间会有一种方式是：客服进行提交创建，如果有相关图片操作，会联系用户，再进行截图上传（更新上传？）</li><li>2、退钱业务所有的走一遍客诉</li><li>3、</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240417130556.png" alt="image.png"></p><p>佣金抽取</p><ul><li>司机和货主都是用户</li><li>平台的收益方式是进行收佣操作（最开始是免费）</li><li>司机接单需要放置押金（类似卡车运输货物的操作）</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240417132902.png" alt="image.png"></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/%E9%87%8D%E5%A4%8D%E6%8F%90%E4%BA%A4aop%E4%BB%A3%E7%A0%81.jpg" alt="重复提交aop代码.jpg"></p>`,84)])])}const g=i(e,[["render",n]]);export{d as __pageData,g as default};
